css:
.fh {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
  gap: var(--os-space-xl);
  align-items: center;
}
.fh__eyebrow {
  margin: 0 0 var(--os-space-md);
  font-family: var(--os-font-label);
  font-size: var(--os-type-eyebrow-font-size);
  letter-spacing: var(--os-type-eyebrow-letter-spacing);
  text-transform: var(--os-type-eyebrow-text-transform);
  color: var(--os-eyebrow-color);
  animation: fhrise 700ms var(--os-motion-ease, ease) both;
}
.fh__title {
  margin: 0;
  font-family: var(--os-font-heading);
  font-weight: var(--os-font-weight-heading);
  font-size: var(--os-type-display-font-size);
  line-height: var(--os-type-display-line-height);
  letter-spacing: var(--os-type-display-letter-spacing);
  color: var(--os-color-heading);
  text-wrap: balance;
}
.fh__em { position: relative; display: inline-block; white-space: nowrap; }
.fh__scribble {
  position: absolute;
  left: -3%;
  bottom: -0.16em;
  width: 106%;
  height: 0.3em;
  overflow: visible;
  pointer-events: none;
}
.fh__scribble path {
  fill: none;
  stroke: var(--os-color-accent);
  stroke-width: 7;
  stroke-linecap: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: fhdraw 800ms var(--os-motion-ease, ease) 1000ms forwards;
}
.fh--split .fh__w,
.fh--split .fh__em {
  display: inline-block;
  opacity: 0;
  animation: fhword 750ms cubic-bezier(0.2, 0.7, 0.2, 1) both;
  animation-delay: calc(var(--i, 0) * 80ms + 100ms);
}
.fh__intro {
  margin-top: var(--os-space-lg);
  max-width: 34em;
  font-size: var(--os-type-lead-font-size);
  line-height: var(--os-type-lead-line-height);
  color: var(--os-color-text);
  animation: fhrise 800ms var(--os-motion-ease, ease) 500ms both;
}
.fh__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--os-space-lg);
  margin-top: var(--os-space-xl);
  animation: fhrise 800ms var(--os-motion-ease, ease) 650ms both;
}
.fh__more {
  color: var(--os-color-link);
  font-family: var(--os-font-label);
  text-decoration: none;
  border-bottom: 1px solid currentColor;
  padding-bottom: 2px;
}
.fh__more:hover { border-bottom-width: 2px; }
.fh__note {
  margin: var(--os-space-md) 0 0;
  font-family: var(--os-font-label);
  font-size: var(--os-type-small-font-size);
  color: var(--os-color-text-muted);
  animation: fhrise 800ms var(--os-motion-ease, ease) 800ms both;
}
.fh__art {
  position: relative;
  width: 100%;
  max-width: 34rem;
  aspect-ratio: 1 / 1;
  margin-inline: auto;
  animation: fhrise 900ms var(--os-motion-ease, ease) 200ms both;
}
.fh__sun {
  position: absolute;
  top: 0;
  right: 2%;
  width: 74%;
  aspect-ratio: 1;
  background: var(--os-color-ochre);
  border-radius: 52% 48% 55% 45% / 48% 54% 46% 52%;
  transform: translate3d(0, calc(var(--fh-y, 0) * -0.12px), 0);
}
.fh__leaf {
  position: absolute;
  left: 0;
  top: 30%;
  width: 20%;
  aspect-ratio: 1;
  background: var(--os-color-moss);
  border-radius: 0 100% 0 100%;
  transform: translate3d(0, calc(var(--fh-y, 0) * 0.08px), 0) rotate(-14deg);
}
.fh__svg {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 4%;
  width: 100%;
  height: auto;
  overflow: visible;
  transform: translate3d(0, calc(var(--fh-y, 0) * -0.04px), 0);
}
.fh__svg .ln {
  stroke: var(--os-color-heading);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: fhdraw 900ms var(--os-motion-ease, ease) var(--d, 0ms) forwards;
}
.fh__svg .ac { stroke: var(--os-color-accent); }
.fh__svg .fl, .fh__svg .fs { fill: var(--f); fill-opacity: 0; }
.fh__svg .fl {
  animation: fhdraw 900ms var(--os-motion-ease, ease) var(--d, 0ms) forwards, fhfill 600ms ease calc(var(--d, 0ms) + 600ms) forwards;
}
.fh__svg .fs {
  animation: fhdraw 900ms var(--os-motion-ease, ease) var(--d, 0ms) forwards, fhfill 400ms ease var(--d, 0ms) forwards;
}
.fh__badge {
  position: absolute;
  left: 3%;
  bottom: 0;
  width: 28%;
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--os-color-accent);
  color: var(--os-color-accent-text);
  box-shadow: 3px 3px 0 var(--os-color-heading);
}
.fh__badgetxt {
  padding: 0 12%;
  text-align: center;
  font-family: var(--os-font-label);
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.fh--ring .fh__badgetxt {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.fh__ring { position: absolute; inset: 0; animation: fhspin 24s linear infinite; }
.fh__ring span {
  position: absolute;
  left: 50%;
  top: 7%;
  height: 43%;
  font-family: var(--os-font-label);
  font-size: 0.68rem;
  text-transform: uppercase;
  transform-origin: 50% 100%;
  transform: translateX(-50%) rotate(var(--a, 0deg));
}
.fh__spark { position: absolute; width: 20%; height: 20%; fill: currentColor; }
.fh:not(.fh--ring) .fh__spark { display: none; }
@keyframes fhrise { from { opacity: 0; transform: translateY(var(--os-motion-reveal-distance, 16px)); } to { opacity: 1; transform: none; } }
@keyframes fhword { from { opacity: 0; transform: translateY(0.45em) rotate(2deg); } to { opacity: 1; transform: none; } }
@keyframes fhdraw { to { stroke-dashoffset: 0; } }
@keyframes fhfill { to { fill-opacity: 1; } }
@keyframes fhspin { to { transform: rotate(360deg); } }
@media (max-width: 1199px) {
  .fh__title { font-size: var(--os-type-h1-font-size); line-height: var(--os-type-h1-line-height); }
}
@media (max-width: 767px) {
  .fh { grid-template-columns: minmax(0, 1fr); gap: var(--os-space-lg); }
  .fh__art { max-width: 22rem; }
}
@media (prefers-reduced-motion: reduce) {
  .fh__eyebrow, .fh__intro, .fh__actions, .fh__note, .fh__art, .fh__ring { animation: none; }
  .fh__scribble path, .fh__svg .ln { animation: none; stroke-dashoffset: 0; }
  .fh__svg .fl, .fh__svg .fs { animation: none; fill-opacity: 1; }
}

js:
const el = root.querySelector('.fh');
if (!el) return;
const ring = el.querySelector('[data-ring]');
const txt = el.querySelector('.fh__badgetxt');
if (ring && txt) {
  const s = (txt.textContent || '').trim();
  const chars = Array.from((s + ' · ').repeat(2));
  chars.forEach((c, i) => {
    const sp = document.createElement('span');
    sp.textContent = c === ' ' ? ' ' : c;
    sp.style.setProperty('--a', (i * 360 / chars.length) + 'deg');
    ring.appendChild(sp);
  });
  el.classList.add('fh--ring');
}
if (ctx.reducedMotion) return;
let n = 0;
el.querySelectorAll('.fh__title > *').forEach((kid) => {
  if (kid.hasAttribute('data-split')) {
    const words = (kid.textContent || '').trim().split(/\s+/).filter(Boolean);
    kid.textContent = '';
    words.forEach((w, i) => {
      const s = document.createElement('span');
      s.className = 'fh__w';
      s.style.setProperty('--i', String(n));
      n += 1;
      s.textContent = w;
      kid.appendChild(s);
      if (i < words.length - 1) kid.appendChild(document.createTextNode(' '));
    });
  } else {
    kid.style.setProperty('--i', String(n));
    n += 1;
  }
});
el.classList.add('fh--split');
let queued = false;
const update = () => {
  queued = false;
  const top = el.getBoundingClientRect().top;
  el.style.setProperty('--fh-y', String(Math.round(Math.max(0, -top))));
};
window.addEventListener('scroll', () => {
  if (!queued) {
    queued = true;
    requestAnimationFrame(update);
  }
}, { passive: true });
update();
